import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const packages = [
  "@fontsource-variable/geist",
  "@fontsource-variable/noto-sans-sc",
];

const sections = [
  "/* Generated by scripts/generate-fonts-css.mjs. Do not edit by hand. */",
  "/* Re-run: node scripts/generate-fonts-css.mjs after updating font packages. */",
  "",
];

for (const pkg of packages) {
  const indexPath = resolve(root, "node_modules", pkg, "index.css");
  const raw = readFileSync(indexPath, "utf8");
  const rewritten = raw
    .replaceAll("font-display: swap;", "font-display: fallback;")
    .replaceAll("url(./files/", `url(${pkg}/files/`);
  sections.push(`/* === ${pkg} === */`, rewritten.trim(), "");
}

const outPath = resolve(root, "apps/web/src/styles/fonts.css");
writeFileSync(outPath, sections.join("\n"), "utf8");
console.log(`Wrote ${outPath}`);
